guidedExercise.solutionCode:
def choose_next(state, route_map):
    route = state['intent']
    if route not in route_map:
        raise ValueError('unmapped route')
    return route_map[route]

guidedExercise.unitTests:
assert choose_next({'intent':'billing'}, {'billing':'billing_node'}) == 'billing_node'
try:
    choose_next({'intent':'admin'}, {'billing':'billing_node'})
    raise AssertionError('unknown route should fail')
except ValueError:
    pass
